import{_ as a,o as i,a as t,b as r}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/Reduce_summary.BqtmCz8D.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"C++类库API","link":"/guide/programming_guide/library_api/library_api"},{"text":"基础API","link":"/guide/programming_guide/library_api/basic_api/overview"},{"text":"常用操作速查指导","link":"/guide/programming_guide/library_api/basic_api/quick_reference/how_to_use_mask_api"},{"text":"如何使用归约计算API","link":"/guide/programming_guide/library_api/basic_api/quick_reference/how_to_use_reduction_api"}]},"headers":[],"relativePath":"guide/programming_guide/library_api/basic_api/quick_reference/how_to_use_reduction_api.md","filePath":"guide/programming_guide/library_api/basic_api/quick_reference/how_to_use_reduction_api.md","lastUpdated":1786949923000}'),d={name:"guide/programming_guide/library_api/basic_api/quick_reference/how_to_use_reduction_api.md"};function o(_,e,l,p,u,n){return i(),t("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>如何使用归约计算API<span id="ZH-CN_TOPIC_0000002271364328"></span></h1><p>归约指令将数据集合简化为单一值或者更小的集合。按照归约操作的数据范围的不同，归约指令分为以下几种，可参考<a href="#zh-cn_topic_0000002267504648_fig16735034112710">归约指令示意图</a>：</p><ul><li>ReduceMax/ReduceMin/ReduceSum：对所有的输入数据做归约操作，得到最大值和最大值索引/最小值和最小值索引/数据总和。</li><li>ReduceRepeat：对每个repeat内的输入数据做归约操作，根据模板参数<code>ReduceType</code>指定求最大值/最小值/求和，得到每个repeat内的最大值和最大值索引/最小值和最小值索引/数据总和。返回索引时返回的是repeat内部索引。</li><li>ReduceDataBlock：对每个DataBlock内的输入数据做归约操作，根据模板参数<code>ReduceType</code>指定求最大值/最小值/求和，得到每个DataBlock内的最大值/最小值/数据总和。</li><li>ReducePairElem：对相邻两个（奇偶）元素进行归约操作，当前仅支持根据模板参数<code>ReduceType::SUM</code>求和，例如（a1, a2, a3, a4, a5, a6...），归约后结果为（a1+a2, a3+a4, a5+a6, ......）。</li></ul><p><strong>图1</strong> 归约指令示意图<span id="zh-cn_topic_0000002267504648_fig16735034112710"></span><br><img src="'+c+'" alt title="归约指令示意图"></p><p>针对归约指令，和其他的基础API一样也提供了<strong>tensor高维切分计算</strong>接口，可充分发挥硬件优势，支持开发者控制指令的<strong>迭代执行</strong>和操作数的<strong>地址间隔</strong>，功能更加灵活。但具体参数的单位和约束与<a href="../interface_classification/high_dim_split_api.html">基础API</a>略有不同，下文将对这些差异点进行介绍。</p><ul><li><p><strong>mask</strong>：用于控制每次迭代内参与计算的元素，mask参数的使用方法和基础API通用的使用方法一致。</p></li><li><p><strong>repeatTime</strong>：迭代次数，开发者通过repeatTime来配置迭代次数，从而控制指令的多次迭代执行。</p><ul><li>ReduceMax/ReduceMin/ReduceSum对于repeatTime超过255的情况，在API内部进行了处理，所以repeatTime支持更大的取值范围，保证不超过int32_t最大值的范围即可。</li><li>ReduceRepeat/ReduceDataBlock/ReducePairElem和其他基础API一样，repeatTime要求不超过255。</li></ul></li><li><p><strong>repeatStride</strong>：表示相邻迭代间的地址步长。</p><ul><li>ReduceMax/ReduceMin/ReduceSum指令的目的操作数会归约成一个最大值/最小值/总和，所以其目的操作数不支持配置repeatStride。仅源操作数支持repeatStride，其含义、单位（datablock）和基础API通用说明一致。</li><li>ReduceRepeat/ReduceDataBlock/ReducePairElem源操作数和目的操作数都支持配置repeatStride，源操作数repeatStride的含义、单位（DataBlock）和基础API通用说明一致。目的操作数repeatStride的含义、单位和基础API通用说明有差异，因为归约后，目的操作数的长度会变短，比如ReduceRepeat归约后每个repeat会合并为一个值，所以迭代之间的间隔不能再使用一个DataBlock为单位，而以一个repeat归约后的长度为单位。</li></ul></li><li><p><strong>dataBlockStride</strong>：表示单次迭代内datablock的地址步长。</p><ul><li>ReduceMax/ReduceMin/ReduceSum指令的目的操作数会归约成一个最大值/最小值/总和，所以其目的操作数不支持配置dataBlockStride。源操作数也不支持dataBlockStride。</li><li>ReduceRepeat/ReduceDataBlock/ReducePairElem源操作数支持配置dataBlockStride，源操作数dataBlockStride的含义、单位（DataBlock）和基础API通用说明一致。目的操作数不支持dataBlockStride，因为归约后，目的操作数的长度会变短，比如ReduceRepeat归约后每个repeat会合并为一个值，不再有迭代内DataBlock和地址间隔的概念。</li></ul></li></ul></article></div>',1)])])}const m=a(d,[["render",o]]);export{g as __pageData,m as default};
